  const ms = Date.now() - t0;
  let logged = false;
  try {
    logged = fs8.readFileSync(path9.join(tmp, "events.jsonl"), "utf8").includes('"doctor"');
  } catch {
  }
  fs8.rmSync(tmp, { recursive: true, force: true });
  if (r.status === 0 && logged) return { ok: true, ms, detail: "" };
